import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { activityTypeSchema, type ActivityType } from "./activity-type.js";
import { cause9Schema, type Cause9 } from "./cause9.js";

export type ScheduleActivityTaskFailedEventAttributes = {
  activityType: ActivityType;
  /** The activityId provided in the ScheduleActivityTask decision that failed. */
  activityId: string;
  /**
   * The cause of the failure. This information is generated by the system and can be useful for
   * diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it
   * lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage
   * Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
   */
  cause: Cause9;
  /**
   * The ID of the DecisionTaskCompleted event corresponding to the decision that resulted in the
   * scheduling of this activity task. This information can be useful for diagnosing problems by
   * tracing back the chain of events leading up to this event.
   */
  decisionTaskCompletedEventId: number;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const scheduleActivityTaskFailedEventAttributesSchema: Schema<ScheduleActivityTaskFailedEventAttributes> =
  s.object<ScheduleActivityTaskFailedEventAttributes>(
    {
      activityType: activityTypeSchema,
      activityId: s.string(),
      cause: cause9Schema,
      decisionTaskCompletedEventId: s.int(),
    },
    { additionalProperties: s.json() },
  );
